from pathlib import Path
from base64 import b64encode

ROOT = Path('/home/ubuntu')
ASSET = ROOT / 'nano_ebook_assets'
OUT = ROOT / 'เอกสารประกอบการสอน_นาโนเทคโนโลยีเชิงฟิสิกส์.html'

def image_data(name):
    b64 = b64encode((ASSET / name).read_bytes()).decode('ascii')
    return f'data:image/png;base64,{b64}'

fig_surface = image_data('fig_surface_area_ratio.png')
fig_dls = image_data('fig_simulated_dls.png')
